"use strict";(self.webpackChunk_ai_autistic_intelligence_docusaurus_theme=self.webpackChunk_ai_autistic_intelligence_docusaurus_theme||[]).push([["1877"],{3982(e){e.exports=JSON.parse('{"version":{"pluginId":"ferrox-front","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/docs/ferrox-front/overview","label":"Overview","docId":"overview","unlisted":false},{"type":"link","href":"/docs/ferrox-front/security/","label":"Zero-Trust Wasm Security, WebCrypto & XSS Sanitization","docId":"security/security","unlisted":false},{"type":"category","label":"architectures","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ferrox-front/architectures/architecture","label":"Core WebAssembly System Architecture","docId":"architectures/architecture","unlisted":false}]},{"type":"category","label":"fundamentals","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ferrox-front/fundamentals/core","label":"Core Kernel, Context Providers & Resource Managers","docId":"fundamentals/core","unlisted":false},{"type":"link","href":"/docs/ferrox-front/fundamentals/reactivity","label":"Fine-Grained Reactive Primitives (Signals, Memos & Effects)","docId":"fundamentals/reactivity","unlisted":false},{"type":"link","href":"/docs/ferrox-front/fundamentals/macros","label":"Procedural Macros, Component Annotations & Code Generation","docId":"fundamentals/macros","unlisted":false},{"type":"link","href":"/docs/ferrox-front/fundamentals/routing","label":"Client-Side Router, Route Guards & Lazy Loading","docId":"fundamentals/routing","unlisted":false},{"type":"link","href":"/docs/ferrox-front/fundamentals/templates","label":"Virtual DOM Templates, JSX Engine & HTML Macros","docId":"fundamentals/templates","unlisted":false}]},{"type":"category","label":"overview","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ferrox-front/overview/intro","label":"Introduction & Ferrox-Front Architecture","docId":"overview/intro","unlisted":false},{"type":"link","href":"/docs/ferrox-front/overview/quickstart","label":"Quickstart Guide","docId":"overview/quickstart","unlisted":false}]},{"type":"category","label":"transports","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ferrox-front/transports/ws","label":"Real-Time WebSockets Engine (ferrox-front-ws)","docId":"transports/ws","unlisted":false}]},{"type":"category","label":"ui","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ferrox-front/ui/ui-components","label":"Glassmorphism Design System (ferrox-front-ui)","docId":"ui/ui-components","unlisted":false},{"type":"link","href":"/docs/ferrox-front/ui/components","label":"Component Library & Interactive Playground","docId":"ui/components","unlisted":false}]}]},"docs":{"architectures/architecture":{"id":"architectures/architecture","title":"Core WebAssembly System Architecture","description":"The ferrox-front architecture is designed around zero-cost abstractions, fine-grained reactive dependency graphs, single-threaded browser thread execution, WebAssembly linear memory layout, and WebGL rendering acceleration.","sidebar":"tutorialSidebar"},"fundamentals/core":{"id":"fundamentals/core","title":"Core Kernel, Context Providers & Resource Managers","description":"The ferrox-front-core crate is the foundation kernel of the Ferrox WebAssembly frontend framework. It manages component context providers (providecontext, usecontext), async resource loaders (create_resource), effect batch schedulers, and browser lifecycle event hooks.","sidebar":"tutorialSidebar"},"fundamentals/macros":{"id":"fundamentals/macros","title":"Procedural Macros, Component Annotations & Code Generation","description":"The ferrox-front-macro crate provides Rust procedural macros (#[component], view!, derive(Store)) that transform declarative UI components and reactive state structs into optimized WebAssembly execution code.","sidebar":"tutorialSidebar"},"fundamentals/reactivity":{"id":"fundamentals/reactivity","title":"Fine-Grained Reactive Primitives (Signals, Memos & Effects)","description":"The ferrox-front-core reactivity engine provides fine-grained reactive state management in WebAssembly. Built on push-pull signal graphs, it exposes Signal, ReadSignal, WriteSignal, Memo, and Effect primitives without relying on Virtual DOM diffing.","sidebar":"tutorialSidebar"},"fundamentals/routing":{"id":"fundamentals/routing","title":"Client-Side Router, Route Guards & Lazy Loading","description":"The ferrox-front-router crate delivers client-side SPA navigation for WebAssembly apps. It features HTML5 History API integration, route path parameter matching, nested layout outlets, route protection guards, and code-split WebAssembly module lazy loading.","sidebar":"tutorialSidebar"},"fundamentals/templates":{"id":"fundamentals/templates","title":"Virtual DOM Templates, JSX Engine & HTML Macros","description":"The ferrox-front-templates crate delivers zero-allocation HTML templating, WebAssembly compile-time JSX expansion, reactive DOM element patching, and SSR (Server-Side Rendering) string interpolation for Rust web applications.","sidebar":"tutorialSidebar"},"overview":{"id":"overview","title":"Overview","description":"Ferrox Front is a high-performance, WebAssembly (WASM) based frontend framework written in Rust, leveraging the Yew framework under the hood. It provides a robust, type-safe environment for building complex User Interfaces while maintaining near-native performance.","sidebar":"tutorialSidebar"},"overview/intro":{"id":"overview/intro","title":"Introduction & Ferrox-Front Architecture","description":"Welcome to Ferrox-Front, the high-performance WebAssembly (Wasm) frontend framework written in pure Rust. It combines fine-grained reactive signals, compile-time JSX HTML templates, zero-trust cryptographic security, real-time WebSocket state synchronization, and GPU-accelerated WebGL charts into a unified application suite.","sidebar":"tutorialSidebar"},"overview/quickstart":{"id":"overview/quickstart","title":"Quickstart Guide","description":"This guide demonstrates how to install prerequisites, build your first WebAssembly application in Rust using Ferrox Front, and run it in the browser.","sidebar":"tutorialSidebar"},"security/security":{"id":"security/security","title":"Zero-Trust Wasm Security, WebCrypto & XSS Sanitization","description":"The ferrox-front-security crate delivers zero-trust security for Rust WebAssembly applications. It features browser WebCrypto API bindings (AES-256-GCM, RSA-OAEP, ECDSA), zero-copy linear memory wiping (Zeroize), secure storage adapters, and HTML XSS sanitizers.","sidebar":"tutorialSidebar"},"transports/ws":{"id":"transports/ws","title":"Real-Time WebSockets Engine (ferrox-front-ws)","description":"ferrox-front-ws provides an asynchronous WebAssembly WebSocket client engine built natively for Rust frontends. It bridges browser WebSocket APIs (web_sys::WebSocket) with Ferrox Front\'s reactive Signals graph (Signal), enabling low-latency, real-time bi-directional streaming for dashboards, chat applications, financial tickers, and live notification systems.","sidebar":"tutorialSidebar"},"ui/components":{"id":"ui/components","title":"Component Library & Interactive Playground","description":"Explore and interact with the Ferrox Front component library live in your browser using our Nivo-Style Interactive Playground.","sidebar":"tutorialSidebar"},"ui/ui-components":{"id":"ui/ui-components","title":"Glassmorphism Design System (ferrox-front-ui)","description":"ferrox-front-ui provides a complete, enterprise-grade Glassmorphism Design System for WebAssembly applications. It includes Design Tokens, a 12-column responsive layout grid, a Virtualized DataGrid (1,000,000+ rows), and a comprehensive library of pre-styled UI components.","sidebar":"tutorialSidebar"}}}}')}}]);